"""Synchronized complete north water chain on shared world registration."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
def track(equipped):
 entries=[]
 folders=['bill-tread-helmet-north-coherent-v1','bill-swim-transitions-helmet-north-coherent-v1','bill-swim-helmet-north-coherent-v1','bill-swim-transitions-helmet-north-coherent-v1'] if equipped else ['bill-tread-north-coherent-v1','bill-swim-transitions-north-coherent-v1','bill-swim-north-coherent-v1','bill-swim-transitions-north-coherent-v1']
 for folder,key in zip(folders,['tread-north','swim-start-north','swim-north','swim-stop-north']):
  root=HERE.parent/folder;p=json.loads((root/'manifest.json').read_text());state=next(s for s in p['states'] if s['id']==key)
  for file,duration in zip(state['frameFiles'],state['frameDurationsMs']):entries.append({'file':'../'+folder+'/'+file,'duration':duration,'phase':key,'width':p['frameWidth'],'height':p['frameHeight'],'pivot':p['pivot']})
 return {'label':'Shared helmet · complete north water chain' if equipped else 'Bare · complete north water chain','frames':entries}
tracks=[track(False),track(True)]
html='''<!doctype html><meta charset="utf-8"><title>Bill north water transition chain</title><style>body{background:#152027;color:#e6eff1;font:16px system-ui;margin:20px}p{max-width:85ch;color:#bdd0d2}.grid{display:flex;gap:12px;flex-wrap:wrap}.card{background:#22343e;padding:12px}canvas{display:block}button,select{font:inherit;background:#29404a;color:white;padding:6px}</style><h1>Bill — connected north water animations</h1><p>Master-relative tread and swim loops with four authored pitch interiors and exact endpoint joins. Native-scale selected rear helmet shell. Both profiles share960ms loops and520ms start/stop clocks. Installed independent north family:two tanks,three cyan vents and grey rear belt plate. Frozen anatomy/material grading with native selected rear shell. 1137 three-view native frame/clock/phase checks pass;owner acceptance and full-set polish remain.</p><button id="play">Pause</button> <button id="step">Next pose</button> Height <select id="size"><option>148</option><option selected>82</option><option>54</option></select> Speed <select id="speed"><option value="1">1×</option><option value=".5" selected>0.5×</option></select><span id="status"> Loading…</span><div class="grid" id="grid"></div><script>
const tracks=DATA;let time=0,last=performance.now(),playing=true,manual=0;for(const t of tracks){const el=document.createElement('div');el.className='card';el.innerHTML='<strong>'+t.label+'</strong><canvas width="460" height="430"></canvas>';grid.append(el);t.canvas=el.querySelector('canvas')};play.onclick=()=>{playing=!playing;play.textContent=playing?'Pause':'Play'};step.onclick=()=>{playing=false;manual=(manual+1)%24;play.textContent='Play'};
Promise.all(tracks.map(async t=>{t.total=t.frames.reduce((v,f)=>v+f.duration,0);t.images=await Promise.all(t.frames.map(f=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src=f.file+'?v=north-water-v1'})))})).then(()=>{function draw(now){if(playing)time+=(now-last)*Number(speed.value);last=now;let i=manual,v=time%tracks[0].total;if(playing){i=0;while(i<23&&v>=tracks[0].frames[i].duration)v-=tracks[0].frames[i++].duration};const s=Number(size.value)/148;for(const t of tracks){const c=t.canvas.getContext('2d'),f=t.frames[i];c.fillStyle='#22343e';c.fillRect(0,0,460,215);c.fillStyle='#dae1e0';c.fillRect(0,215,460,215);for(const y of [100,315])c.drawImage(t.images[i],230-f.pivot[0]*s,y-f.pivot[1]*s,f.width*s,f.height*s)}document.querySelector('#status').textContent=' Both chains loaded · '+tracks[0].frames[i].phase+' · pose '+(i+1)+'/24';requestAnimationFrame(draw)}requestAnimationFrame(draw)}).catch(e=>document.querySelector('#status').textContent='Load failed '+e);</script>'''
(HERE/'index.html').write_text(html.replace('DATA',json.dumps(tracks)),encoding='utf-8');print('Built complete paired24-reference north water chain')
